/*
 * Parasite Eve's own creatures, registered through the `bestiary` service exactly as an import pack
 * (another game's) or a randomizer would; it is the example to copy. The data is
 * pe_collection_data.h, generated by the bridge (gen_collection_data.py) from the Bestiary draft.
 * The costumes are the Wardrobe's (pe_wardrobe/pe_pack_pe1_costumes.c).
 *
 * Keys ("pe1/rat", "pe1/ex_rat") are saved in players' profiles and must never change: they come
 * from the generated names, in table order, and a repeated name gets "_2", "_3".
 */
#include <ctype.h>
#include <stdio.h>
#include <string.h>

#include "pe_collection.h"
#include "pe_collection_data.h"

#define PE_KEY_MAX 48

static char s_creature_key[PE_CREATURES][PE_KEY_MAX];
static PeCreatureInfo s_info[PE_CREATURES];

static void pe_slug(char *out, size_t size, const char *prefix, const char *name) {
    size_t n = (size_t)snprintf(out, size, "pe1/%s", prefix);
    int gap = 0;
    for (; *name && n + 1 < size; ++name) {
        const unsigned char c = (unsigned char)*name;
        if (isalnum(c)) {
            if (gap && out[n - 1] != '/' && out[n - 1] != '_') out[n++] = '_';
            out[n++] = (char)tolower(c);
            gap = 0;
        } else gap = 1;
    }
    out[n] = 0;
}

static void pe_make_keys(void) {
    static int done;
    int i, j;
    if (done) return;
    done = 1;
    for (i = 0; i < PE_CREATURES; ++i) {
        char base[PE_KEY_MAX];
        int repeat = 1;
        pe_slug(base, sizeof base, g_pe_creatures[i].ex ? "ex_" : "", g_pe_creatures[i].name);
        snprintf(s_creature_key[i], PE_KEY_MAX, "%s", base);
        for (j = 0; j < i; ++j)
            if (strcmp(s_creature_key[j], s_creature_key[i]) == 0) {
                snprintf(s_creature_key[i], PE_KEY_MAX, "%s_%d", base, ++repeat);
                j = -1;                                      /* check the new name from the start */
            }
    }
}

const char *pe_pack_pe1_creature_key(int index) {
    pe_make_keys();
    return index >= 0 && index < PE_CREATURES ? s_creature_key[index] : NULL;
}

void pe_pack_pe1_register(void) {
    const PeBestiaryApi *b = &g_pe_bestiary_api;
    int handle[PE_CREATURES], i;
    pe_make_keys();
    for (i = 0; i < PE_CREATURES; ++i) {
        const PeCreature *c = &g_pe_creatures[i];
        s_info[i] = (PeCreatureInfo){ s_creature_key[i], c->name, c->section, c->boss, c->ex, c->hp, c->defense,
                                      c->weak, c->strong, c->drop, c->steal, c->price_weak, c->price_loot };
        handle[i] = b->add(&s_info[i]);
    }
    for (i = 0; i < PE_CREATURE_KEYS; ++i) {
        const PeCreatureKey *k = &g_pe_creature_keys[i];
        if (k->creature < PE_CREATURES && handle[k->creature] >= 0) b->map(k->map, k->id, handle[k->creature]);
    }
    {
        int form[PE_CREATURES] = {0};             /* model forms, main body first (generated order) */
        for (i = 0; i < PE_CREATURE_MODELS; ++i) {
            const PeCreatureModel *m = &g_pe_creature_models[i];
            PeModelSource src = {PE_MODEL_ROOM, m->actor, m->map, NULL, NULL, NULL};
            if (m->creature < PE_CREATURES && handle[m->creature] >= 0 && form[m->creature] < PE_BESTIARY_MAX_FORMS)
                b->set_model(handle[m->creature], form[m->creature]++, &src);
        }
    }
}
